function updateLegendLobby(){const app=$('app');const theme=state.selected===1&&state.legendEquipped&&!state.roosterEquipped&&!state.buyerGazyavaEquipped?'hero':state.selected===4&&!state.elVorsenEquipped&&state.vorsinMoggedEquipped?'mogg':state.selected===3&&state.sonKingEquipped&&!state.bychkodjonEquipped&&!state.sonGazyavaEquipped&&!state.sonPoorEquipped?'king':'';if(theme){if(app.dataset.legendTheme!==theme)app.dataset.legendTheme=theme;}else if(app.hasAttribute('data-legend-theme'))app.removeAttribute('data-legend-theme');}
