// Wheel: 50k is deliberately rare (1%), to avoid breaking progression.
const wheelRewards=[{value:500,weight:22},{value:1000,weight:20},{value:1500,weight:18},{value:2500,weight:15},{value:5000,weight:11},{value:7500,weight:8},{value:10000,weight:5},{value:50000,weight:1}];
let rouletteBusy=false;
function openRoulette(){
 show(`<div class="roulette-art"><div class="roulette-pointer" id="roulettePointer"></div></div><div class="roulette-controls"><h2>🎰 АЦЕТОН РУЛЕТКА</h2><p>Стоимость вращения — 5 000 🧴 · ❔ = 50 000 🧴</p><p>Баланс: <b id="rouletteBalance">${fmt(state.gold)}</b></p><p id="freeSpinsLabel">🎟️ Гарантированные прокрутки: ${fmt(state.casinoFreeSpins)}</p><div id="rouletteResult" class="roulette-result"></div><button class="roulette-spin" id="rouletteSpin">КРУТИТЬ · 5 000 🧴</button><p>Джекпот выпадает редко — шанс 1%.</p></div>`);
 document.querySelector('.panel').classList.add('roulette-panel');
 $('rouletteSpin').onclick=spinRoulette;
 $('rouletteSpin').disabled=state.gold<5000&&state.casinoFreeSpins<1;$('rouletteSpin').textContent=state.casinoFreeSpins>0?'🎟️ КРУТИТЬ · ГАРАНТИЯ 50 000':'КРУТИТЬ · 5 000 🧴';
}
let roulettePointerAngle=0;
function spinRoulette(){
 if(rouletteBusy||(state.gold<5000&&state.casinoFreeSpins<1))return;
 const guaranteed=state.casinoFreeSpins>0;
 rouletteBusy=true;startMusic();if(guaranteed)state.casinoFreeSpins--;else state.gold-=5000;state.rouletteSpins=(state.rouletteSpins||0)+1;save();render();
 const button=$('rouletteSpin'),pointer=$('roulettePointer'),result=$('rouletteResult');
 button.disabled=true;button.textContent='СТРЕЛКА КРУТИТСЯ...';result.textContent='🎰 Стрелка выбирает приз...';
 let n=Math.random()*100,reward=guaranteed?50000:wheelRewards[0].value;
 if(!guaranteed)for(const p of wheelRewards){n-=p.weight;if(n<0){reward=p.value;break}}
 // Sectors are aligned to the static roulette artwork, clockwise from the top.
 // The pointer starts at the top and finishes at the selected prize sector.
 const prizeAngles={10000:0,1500:47,2500:91,5000:137,7500:181,500:224,1000:270,50000:315};
 const target=prizeAngles[reward] ?? 0;
 const current=((roulettePointerAngle%360)+360)%360;
 const extra=(target-current+360)%360;
 roulettePointerAngle+=360*6+extra;
 pointer.style.transition='none';pointer.style.transform=`rotate(${roulettePointerAngle-360*6-extra}deg)`;
 void pointer.offsetWidth;
 pointer.style.transition='transform 4.2s cubic-bezier(.13,.75,.12,1)';
 let ticks=0;const tickTimer=setInterval(()=>{if(++ticks>27){clearInterval(tickTimer);return}rouletteTick()},145);
 pointer.style.transform=`rotate(${roulettePointerAngle}deg)`;
 setTimeout(()=>{
  gainGold(reward);save();render();rouletteBusy=false;winSound(reward);
  result.textContent='ВЫИГРЫШ: +'+fmt(reward)+' 🧴';
  $('rouletteBalance').textContent=fmt(state.gold);
  button.disabled=state.gold<5000&&state.casinoFreeSpins<1;button.textContent=state.casinoFreeSpins>0?'🎟️ КРУТИТЬ · ГАРАНТИЯ 50 000':'КРУТИТЬ ЕЩЁ · 5 000 🧴';$('freeSpinsLabel').textContent='🎟️ Гарантированные прокрутки: '+fmt(state.casinoFreeSpins);
  if(reward===50000)jackpotAnimation();else toast('🎉 +'+fmt(reward)+' ацетончиков!');
 },4300);
}
function jackpotAnimation(){const el=$('jackpot');el.classList.add('active');for(let i=0;i<95;i++){let p=document.createElement('i');p.className='jackpot-particle';p.style.left=Math.random()*100+'%';p.style.top=-Math.random()*60+'%';p.style.animationDelay=Math.random()*1.2+'s';el.append(p)}try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();if(state.volume>0){const t=audio.currentTime;[523,659,784,1047,1318].forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,t+i*.13);g.gain.exponentialRampToValueAtTime(.13*state.volume/100,t+i*.13+.03);g.gain.exponentialRampToValueAtTime(.0001,t+i*.13+.5);o.connect(g).connect(audio.destination);o.start(t+i*.13);o.stop(t+i*.13+.52)})}}catch{}setTimeout(()=>{el.classList.remove('active');el.querySelectorAll('.jackpot-particle').forEach(x=>x.remove())},3500)}
function adminGrantAllSkins(){if(!state.admin)return false;for(const key of ['sonGazyavaOwned', 'buyerGazyavaOwned', 'roosterOwned', 'kingLohOwned', 'legendOwned', 'syava67Owned', 'bychkodjonOwned', 'elVorsenOwned', 'horrorRoyalOwned', 'horrorPinkOwned', 'horrorBrokenOwned', 'horrorProducerOwned', 'sonPoorOwned', 'sonKingOwned', 'vorsyazavaOwned', 'vorsinMoggedOwned', 'wheelScooterOwned'])state[key]=true;save();render();return true;}
let adminGuaranteedReward=false;
const adminCaseRarity={syava:'',forest:'',bull:'',gazyava:'',vorsin:''};
const adminCaseOptions={syava:['Обычная','Редкая','Эпическая','Мифическая','Легендарная'],forest:['Уёбская','Редкая','Эпическая','Легендарная'],bull:['Уёбская','Редкая','Эпическая','Мифическая','Легендарная','Бычок'],gazyava:['Уёбская','Редкая','Эпическая','Мифическая','Скупщик газявы','Производитель Газявы'],vorsin:['Сява67','Эль Ворсён','Бычкоджон','Кочстянчик','Ворсин']};
function adminCaseChoice(kind,items){return state.admin===true&&adminCaseRarity[kind]?items.find(i=>i.rarity===adminCaseRarity[kind]||i.name===adminCaseRarity[kind])||null:null;}
function adminCaseSelect(kind){return `<select class="admin-level-input" id="adminCase_${kind}" aria-label="Редкость награды"><option value="">Обычные шансы</option>${adminCaseOptions[kind].map(r=>`<option value="${r}" ${adminCaseRarity[kind]===r?'selected':''}>${r}</option>`).join('')}</select>`;}

function adminGuaranteeActive(){return state.admin===true&&adminGuaranteedReward;}
function adminRunPreview(kind){if(!state.admin)return;try{if(typeof window.openAdminVorsinPreview!=='function')throw new Error('Модуль анимации не загрузился');window.openAdminVorsinPreview(kind);}catch(e){console.error(e);toast('Не удалось открыть тест: '+e.message);}}
function adminRunWheelPreview(index){if(!state.admin)return;try{if(typeof window.openAdminWheelTest!=='function')throw new Error('Модуль тестирования не загрузился');window.openAdminWheelTest(index);}catch(e){console.error(e);toast('Не удалось открыть тест: '+e.message);}}
function openAdmin(){if(!state.admin)return;const v=levelInfo(),names=['Туберкулезный','Костянчик','Святосява','Бычок','Ворсин'];show(`<h2>👑 Админ-панель</h2><h3>Баланс</h3><input id="adminAmount" class="admin-level-input" type="number" min="1" max="1000000000" value="10000"><button id="adminAdd" class="roulette-spin">Начислить ацетончики</button><h3>Уровни и циклы</h3><div class="level-admin-grid"><label>Завершённые циклы<input id="adminMainLevel" class="admin-level-input" type="number" min="0" max="999" value="${v.main}"></label><label>Уровень цикла<input id="adminCycleLevel" class="admin-level-input" type="number" min="0" max="59" value="${v.level}"></label></div><button id="adminLevelSet" class="roulette-spin">Установить уровень</button><button id="adminRestoreRoadKeys" class="roulette-spin" style="margin-top:8px">Восстановить ключи по уровню</button><p class="small">Для исправления старого сохранения: доводит запас ключей до начислений за пройденные уровни. Для Газявы учитываются списания; для остальных кейсов потраченные ключи не учитываются.</p><h3>Персонажи</h3><div class="level-admin-grid admin-characters-grid">${names.map((n,i)=>`<button class="roulette-spin" id="adminChar${i}">${state.owned[i]?'✅ ':'➕ '}${n}</button>`).join('')}</div><h3>Скины</h3><button id="adminGiveAllSkins" class="roulette-spin" style="margin-top:6px">Выдать все скины</button><h3>Бесплатные прокрутки шерифа</h3><p>Доступно: ${fmt(sheriffLevelAvailable())}</p><input id="adminSpinCount" class="admin-level-input" type="number" min="1" max="100" value="5"><button id="adminGiveSpins" class="roulette-spin">Выдать прокрутки</button><h3>Гарант главной награды</h3><button id="adminGuarantee" type="button" aria-pressed="${adminGuaranteeActive()}" class="roulette-spin" style="margin:6px 0 8px;${adminGuaranteeActive()?'background:linear-gradient(#68e89a,#248449);color:#092914':''}">Гарант 100% · ${adminGuaranteeActive()?'ВКЛ':'ВЫКЛ'}</button><p class="small">Шериф, MOGGED и Царь. Только доступные бесплатные награды за уровни. Режим сбрасывается при перезапуске игры.</p><h3>Гарант кейсов</h3><p class="small">Выбери редкость награды за уровень. Настройки отдельных кейсов сбрасываются при перезапуске.</p><label>Кейс Сява${adminCaseSelect('syava')}</label><label>Изумрудный кейс${adminCaseSelect('forest')}</label><label>Кейс Бычка${adminCaseSelect('bull')}</label><label>Газява${adminCaseSelect('gazyava')}</label><label>Кейс Ворсина${adminCaseSelect('vorsin')}</label><div class="admin-wheel-tests"><button type="button" id="adminEmeraldTest" class="roulette-spin">Тест анимации Изумрудного короля</button><button type="button" id="vorsinPreview" class="roulette-spin">Тест анимации Ворсина</button><button type="button" id="vorsinPreviewBull" class="roulette-spin">Тест Бычкоджона</button><button type="button" id="vorsinPreviewHero" class="roulette-spin">Тест Кочстянчика</button></div><button type="button" id="adminCaseClear" class="roulette-spin" style="margin:6px 0 12px">Сбросить гарант кейсов</button><h3>Рулетки · тест анимаций</h3><p class="small">Доступно только администратору. Тест не расходует валюту и не начисляет награды.</p><div class="admin-wheel-tests"><button type="button" id="adminMoggedTest" class="roulette-spin">MOGGED — открыть тест</button><button type="button" id="adminRoyalTest" class="roulette-spin">Королевская — открыть тест</button></div><p id="adminStatus" role="status"></p>`);const valid=(n,max)=>Number.isSafeInteger(n)&&n>=1&&n<=max;$('adminGuarantee').onclick=()=>{if(!state.admin)return;adminGuaranteedReward=!adminGuaranteedReward;const b=$('adminGuarantee');b.textContent='Гарант 100% · '+(adminGuaranteeActive()?'ВКЛ':'ВЫКЛ');b.setAttribute('aria-pressed',String(adminGuaranteeActive()));b.style.background=adminGuaranteeActive()?'linear-gradient(#68e89a,#248449)':'';b.style.color=adminGuaranteeActive()?'#092914':'';};for(const kind of Object.keys(adminCaseOptions)){$('adminCase_'+kind).onchange=e=>{if(!state.admin)return;const value=e.target.value;adminCaseRarity[kind]=adminCaseOptions[kind].includes(value)?value:'';};}$('adminCaseClear').onclick=()=>{if(!state.admin)return;adminCaseRarity.syava=adminCaseRarity.forest=adminCaseRarity.bull=adminCaseRarity.gazyava=adminCaseRarity.vorsin='';for(const kind of Object.keys(adminCaseOptions)){const select=$('adminCase_'+kind);if(select)select.value='';}toast('Гаранты кейсов сброшены');};$('adminEmeraldTest').onclick=()=>{if(!state.admin)return;try{if(typeof window.openAdminEmeraldPreview!=='function')throw new Error('Модуль анимации не загрузился');window.openAdminEmeraldPreview();}catch(e){console.error(e);toast('Не удалось открыть тест: '+e.message);}};$('vorsinPreview').onclick=()=>adminRunPreview('vorsin');$('vorsinPreviewBull').onclick=()=>adminRunPreview('bull');$('vorsinPreviewHero').onclick=()=>adminRunPreview('hero');$('adminGiveAllSkins').onclick=()=>{if(!adminGrantAllSkins())return;openAdmin();$('adminStatus').textContent='Все скины выданы';toast('Все скины получены!');};$('adminMoggedTest').onclick=()=>adminRunWheelPreview(1);$('adminRoyalTest').onclick=()=>adminRunWheelPreview(2);$('adminAdd').onclick=()=>{const n=Number($('adminAmount').value);if(!valid(n,1000000000))return;gainGold(n);save();render();openAdmin();};$('adminRestoreRoadKeys').onclick=()=>{if(!state.admin)return;const added=restoreRoadKeys();save();render();openAdmin();$('adminStatus').textContent='Восстановлено ключей: '+fmt(added);};$('adminLevelSet').onclick=()=>{const m=Number($('adminMainLevel').value),l=Number($('adminCycleLevel').value);if(!Number.isSafeInteger(m)||m<0||m>=MAX_CYCLES||!Number.isInteger(l)||l<0||l>59)return;setXP(cycleStart(m)+BigInt(levelThreshold(l))*cycleScale(m));syncProgress(true);save();render();openAdmin();};names.forEach((n,i)=>{$('adminChar'+i).onclick=()=>{state.owned[i]=true;save();render();openAdmin();};});$('adminGiveSpins').onclick=()=>{const n=Number($('adminSpinCount').value);if(!valid(n,100))return;state.sheriffBonusSpins+=n;save();render();openAdmin();$('adminStatus').textContent='Выдано прокруток: '+fmt(n);};}


const upgradeIcons={tap:'<path d="M13 2 4 14h7l-1 8 10-12h-7z"/>',passive:'<path d="M4 20h16M6 17v-5h3v5m3 0V8h3v9m3 0V4h3v13"/><path d="m3 9 5-4 4 1 6-4"/>',golden:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/><path d="M19 2v4m-2-2h4M4 18v4m-2-2h4"/>',lucky:'<path d="M12 21v-8m0 0C0 17 1 3 8 6c-2-8 10-8 8 0 7-3 8 11-4 7Z"/>',auto:'<rect x="4" y="7" width="16" height="13" rx="4"/><path d="M12 3v4M9 12h.1m5.9 0h.1M8 16h8M2 11v5m20-5v5"/>'};
function upgradeIcon(id){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${upgradeIcons[id]}</svg>`;}
function passivePrice(l=state.passiveLevel){return l>=25?null:20000*3**l;}
function goldenPrice(l=state.goldenLevel){return l>=9?null:l===0?100000:1000000*5**(l-1);}
function nextTapPower(){return tapPower(Math.min(10,state.level+1));}
function upgradeData(){const l=state.goldenLevel,p=state.passiveLevel,canAuto=state.owned.slice(1).some(Boolean);return [
 {id:'tap',name:'Сила тапа',sub:'Основное улучшение',level:state.level,max:10,now:'+'+fmt(tapPower()),next:'+'+fmt(nextTapPower()),price:state.level>=10?null:costs[state.level],desc:'Увеличивает базовую силу нажатия.'},
 {id:'passive',name:'Пассивный доход',sub:'Доход каждую секунду',level:p,max:25,now:'+'+fmt(passiveIncome())+'/с',next:'+'+fmt(passiveIncome(Math.min(25,p+1)))+'/с',price:passivePrice(),desc:'Работает, пока игра открыта и активна. Каждый уровень +1/с.'},
 {id:'golden',name:'Золотой тап',sub:'Каждое 100-е ручное нажатие',level:l,max:9,now:'×'+(l+1),next:'×'+Math.min(10,l+2),price:goldenPrice(),desc:l?'До золотого тапа: '+(100-state.goldenProgress)+' нажатий.':'Первое улучшение открывает множитель ×2.'},
 {id:'lucky',name:'Удачный тап',sub:'Существующее улучшение',level:state.luckyLevel,max:null,now:'+'+fmt(5*state.luckyLevel),next:'+'+fmt(5*(state.luckyLevel+1)),price:1000*(state.luckyLevel+1),desc:'Дополнительная награда за удачный тап (15%).'},
 {id:'auto',name:'Автокликер',sub:'Встроенная автоматизация',level:activeSkin().a||state.autoBought?1:0,max:1,now:activeSkin().a?(state.skinAutoOn!==false?'ВКЛ':'ВЫКЛ'):state.autoBought?(state.autoOn?'ВКЛ':'ВЫКЛ'):'Закрыт',next:activeSkin().a||state.autoBought?'':'Открыт',price:activeSkin().a||state.autoBought?null:autoPrice,desc:activeSkin().a?'Автокликер скина · '+(activeSkin().a/1000).toLocaleString('ru-RU')+' сек.':canAuto?'Не ограничивается антиавтокликером.':'Сначала открой второго персонажа.',locked:!canAuto,toggle:!!activeSkin().a||state.autoBought}
 ];}
function openUpgradeMenu(){show(`<section class="upgrade-menu" id="upgradeMenu"><div class="upgrade-heading"><small>РАЗВИТИЕ ПЕРСОНАЖЕЙ</small><h2>Улучшения</h2><p>Прокачка и автоматизация</p></div><div class="upgrade-wallet"><span>Баланс</span><strong id="upgradeBalance"></strong></div><div class="upgrade-list">${upgradeData().map(d=>`<article class="upgrade-card u-${d.id}" id="uc-${d.id}"><div class="upgrade-cardhead"><div class="upgrade-icon">${upgradeIcon(d.id)}</div><div class="upgrade-title"><b>${d.name}</b><small>${d.sub}</small></div><span class="upgrade-level"></span></div><p class="upgrade-description"></p><div class="upgrade-values"><strong class="upgrade-now"></strong><span class="upgrade-arrow">→</span><strong class="upgrade-next"></strong></div><div class="upgrade-track"><i></i></div><button class="upgrade-buy" type="button" data-upgrade="${d.id}"></button></article>`).join('')}</div><div class="upgrade-protection">${upgradeIcon('auto')}<div><b>Защита ручных тапов включена</b><small>Подозрительные ручные тапы не начисляют доход. Встроенный автокликер работает как обычно.</small></div></div></section>`);$('upgradeMenu').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.upgrade));refreshUpgradeMenu();}
function refreshUpgradeMenu(){const root=$('upgradeMenu');if(!root||!$('modal').classList.contains('show'))return;$('upgradeBalance').textContent=fmt(state.gold);for(const d of upgradeData()){const el=$('uc-'+d.id),b=el.querySelector('button');el.querySelector('.upgrade-level').textContent=d.max===null?'Ур. '+d.level:'Ур. '+d.level+'/'+d.max;el.querySelector('.upgrade-description').textContent=d.desc;el.querySelector('.upgrade-now').textContent=d.now;el.querySelector('.upgrade-next').textContent=d.next;el.querySelector('.upgrade-arrow').hidden=!d.next||d.price===null;el.querySelector('.upgrade-next').hidden=!d.next||d.price===null;el.querySelector('.upgrade-track').hidden=d.max===null;el.querySelector('.upgrade-track i').style.width=(d.max?100*d.level/d.max:0)+'%';b.disabled=!!d.locked||(!d.toggle&&(d.price===null||!Number.isSafeInteger(d.price)||state.gold<d.price));b.textContent=d.toggle?((activeSkin().a?state.skinAutoOn!==false:state.autoOn)?'Выключить':'Включить'):d.price===null?'МАКСИМУМ':fmt(d.price)+' · Улучшить';}}
function buyUpgrade(id){const d=upgradeData().find(x=>x.id===id);if(!d||d.locked)return;if(d.toggle){if(activeSkin().a)state.skinAutoOn=state.skinAutoOn===false;else state.autoOn=!state.autoOn;}else{if(d.price===null||!Number.isSafeInteger(d.price)||state.gold<d.price)return;state.gold-=d.price;if(id==='tap')state.level++;if(id==='passive')state.passiveLevel++;if(id==='golden'){if(!state.goldenLevel)state.goldenProgress=0;state.goldenLevel++;}if(id==='lucky')state.luckyLevel++;if(id==='auto'){state.autoBought=true;state.autoOn=true;}}save();render();}
// Passive income is separate from tap counts and auto taps. No offline catch-up.
setInterval(()=>{const income=passiveIncome();if(document.hidden||income<=0)return;gainGold(income);save();render();},1000);
// Local heuristics only; confirmation is required before regularity-based penalties.
let manualTimes=[],manualIntervals=[],lastManualAttempt=null;
function clearAntiRuntime(){manualTimes=[];manualIntervals=[];lastManualAttempt=null;state.antiStrikes=0;state.antiUntil=0;}
function allowManualTap(e){
 if(!e.isTrusted)return false;
 const t=performance.now(),gap=lastManualAttempt===null?Infinity:t-lastManualAttempt;
 if(gap>2500){manualIntervals=[];manualTimes=[];}
 else if(gap>0){manualIntervals.push(gap);if(manualIntervals.length>60)manualIntervals.shift();}
 lastManualAttempt=t;manualTimes=manualTimes.filter(x=>t-x<1000);manualTimes.push(t);
 if(manualTimes.length>25)return false;
 if(manualIntervals.length>=40){const a=manualIntervals.slice(-40),avg=a.reduce((x,y)=>x+y,0)/a.length,sd=Math.sqrt(a.reduce((x,y)=>x+(y-avg)**2,0)/a.length);if(avg<500&&sd<Math.max(2,avg*.012))return false;}
 return true;
}

function openResetSettings(){show('<h2>⚙️ Настройки</h2><p>Полный сброс удалит баланс, улучшения, купленных персонажей, бонусы и автокликер.</p><button class="reset" id="reset">🗑️ Сбросить весь прогресс</button>');$('reset').onclick=()=>{show('<h2>Точно сбросить?</h2><p>Баланс, покупки и прокачка будут удалены без возможности восстановления.</p><button class="reset" id="confirmreset">Да, удалить весь прогресс</button><button class="buy" id="cancelreset" style="margin-top:12px">Отмена</button>');$('cancelreset').onclick=close;$('confirmreset').onclick=()=>{state={...base,owned:[true,false,false,false,false],syavaCollection:{}};resetTimeRewardClock();clearAntiRuntime();for(const key of ['aceton_clicker_demo_v1','aceton_clicker_demo_v2','aceton_clicker_v3']){try{localStorage.removeItem(key)}catch(e){}}save();render();close();toast('Прогресс сброшен!')}}}render();
